cat > /tmp/test-thresholds.js << 'EOF'
// Quick test of threshold logic
const parseThreshold = (str) => {
  if (!str || typeof str !== 'string') {
    throw new Error(`Threshold must be a string, got ${typeof str}`);
  }

  const parts = str.split('=');
  if (parts.length !== 2) {
    throw new Error(`Threshold must be format 'metric=value', got '${str}'.`);
  }

  const [metricId, minStr] = parts;
  const trimmedMetric = metricId.trim();
  const trimmedMin = minStr.trim();

  if (!trimmedMetric) {
    throw new Error(`Metric ID cannot be empty in threshold '${str}'`);
  }

  if (!trimmedMin) {
    throw new Error(`Threshold value cannot be empty in threshold '${str}'`);
  }

  const min = parseFloat(trimmedMin);

  if (isNaN(min)) {
    throw new Error(
      `Threshold value must be a number, got '${trimmedMin}' in threshold '${str}'`
    );
  }

  if (min < 0 || min > 1) {
    throw new Error(
      `Threshold value must be 0-1, got ${min} in threshold '${str}'`
    );
  }

  return { metric: trimmedMetric, min };
};

// Test cases
console.log('✓ Valid threshold:', parseThreshold('exact_match=0.9'));
console.log('✓ Valid threshold:', parseThreshold('toxicity=0.85'));

try {
  parseThreshold('exact_match=abc');
  console.log('✗ Should have failed on non-numeric value');
} catch (e) {
  console.log('✓ Correctly rejected non-numeric value');
}

try {
  parseThreshold('exact_match=1.5');
  console.log('✗ Should have failed on out-of-range value');
} catch (e) {
  console.log('✓ Correctly rejected out-of-range value');
}

try {
  parseThreshold('exact_match');
  console.log('✗ Should have failed on malformed threshold');
} catch (e) {
  console.log('✓ Correctly rejected malformed threshold');
}

console.log('\nAll threshold parsing tests passed!');
EOF
node /tmp/test-thresholds.js
